package com.andye.warmod.entity.client;
import com.andye.warmod.warhead.client.render.WarheadMesh;import com.mojang.blaze3d.vertex.*;import net.minecraft.util.Mth;import net.minecraft.world.phys.Vec3;
public final class WarheadDebrisTrailRenderer{private WarheadDebrisTrailRenderer(){}public static void render(PoseStack.Pose pose,VertexConsumer b,WarheadDebrisRenderState s){double speed=s.velocity.length();if(speed<.04||s.onGround)return;int lobes=s.distanceToCameraSq<192*192?4:s.distanceToCameraSq<640*640?3:2;Vec3 direction=s.velocity.normalize().scale(-1);float length=(float)Mth.clamp(speed*7,1.5,7),base=(float)Mth.clamp(.12+speed*.42,.12,.65);int red=(s.trailColour>>16)&255,green=(s.trailColour>>8)&255,blue=s.trailColour&255;for(int l=0;l<lobes;l++){float t=(l+.35F)/lobes,cx=(float)(direction.x*length*t),cy=(float)(direction.y*length*t),cz=(float)(direction.z*length*t),radius=base*(1+.75F*t);int alpha=Mth.clamp((int)(120*(1-t)*Math.min(1,speed/.35)),0,160);int segments=8;for(int i=0;i<segments;i++){float a0=Mth.TWO_PI*i/segments,a1=Mth.TWO_PI*(i+1)/segments;v(pose,b,cx+radius*Mth.cos(a0),cy+radius*.35F,cz+radius*Mth.sin(a0),0,0,red,green,blue,alpha);v(pose,b,cx+radius*Mth.cos(a1),cy+radius*.35F,cz+radius*Mth.sin(a1),1,0,red,green,blue,alpha);v(pose,b,cx+radius*Mth.cos(a1),cy-radius*.35F,cz+radius*Mth.sin(a1),1,1,red,green,blue,0);v(pose,b,cx+radius*Mth.cos(a0),cy-radius*.35F,cz+radius*Mth.sin(a0),0,1,red,green,blue,0);}}}private static void v(PoseStack.Pose p,VertexConsumer b,float x,float y,float z,float u,float v,int r,int g,int bl,int a){b.addVertex(p,x,y,z).setColor(r,g,bl,a).setUv(u,v).setOverlay(0).setLight(0xF000F0).setNormal(p,0,1,0);}}
